/**
 * Bulk import of survey questions from CSV (so a questionnaire can be written in a spreadsheet or
 * generated by an AI and loaded in one go). Pure functions, no I/O.
 *
 * Columns (header names are case and accent insensitive; extra columns are ignored):
 *   tipo           likert | alternativas | seleccion_multiple | desplegable | abierta
 *   pregunta       the question text (required)
 *   obligatoria    si / no (default: si)
 *   opciones       options separated by |   (alternativas, seleccion_multiple, desplegable)
 *   otro           si / no: add an "Otro" option with free text (default: no)
 *   min, max       seleccion_multiple: minimum / maximum selections; abierta: minimum / maximum characters
 *   etiqueta_min   text at the low end (likert, alternativas, seleccion_multiple)
 *   etiqueta_max   text at the high end
 */
import { CHOICE_TYPES } from './survey-schema.js';

export const CSV_COLUMNS = ['tipo', 'pregunta', 'obligatoria', 'opciones', 'otro', 'min', 'max', 'etiqueta_min', 'etiqueta_max'];

export const CSV_TEMPLATE = [
  CSV_COLUMNS.join(','),
  'likert,"Las respuestas del asistente fueron útiles",si,,,,,"Nada de acuerdo","Totalmente de acuerdo"',
  'alternativas,"¿Con qué frecuencia usas asistentes de IA?",si,"Nunca|A veces|Casi siempre",si,,,,',
  'seleccion_multiple,"¿Para qué lo usas? (elige hasta 3)",no,"Estudiar|Escribir|Programar|Traducir",si,1,3,,',
  'desplegable,"¿En qué área trabajas?",si,"Educación|Salud|Ingeniería|Otra",no,,,,',
  'abierta,"¿Qué mejorarías de la conversación?",no,,,10,500,,',
].join('\n') + '\n';

const TYPE_NAMES = {
  likert: 'likert', escala: 'likert', scale: 'likert',
  alternativas: 'multiple', multiple: 'multiple', unica: 'multiple', 'opcion unica': 'multiple', radio: 'multiple',
  seleccion_multiple: 'checklist', 'seleccion multiple': 'checklist', checklist: 'checklist', casillas: 'checklist', checkbox: 'checklist',
  desplegable: 'dropdown', dropdown: 'dropdown', lista: 'dropdown', select: 'dropdown',
  abierta: 'text', texto: 'text', text: 'text', open: 'text',
};

const normalize = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').trim().toLowerCase();

/** Splits CSV text into rows of cells. Handles quotes, doubled quotes, CRLF and a BOM. */
export function parseCsvRows(text, delimiter) {
  const src = String(text ?? '').replace(/^﻿/, '');
  const firstLine = src.split(/\r?\n/, 1)[0] || '';
  const delim = delimiter || [';', '\t', ','].map((d) => [d, firstLine.split(d).length]).sort((a, b) => b[1] - a[1])[0][0];
  const rows = [];
  let row = [];
  let cell = '';
  let quoted = false;
  for (let i = 0; i < src.length; i++) {
    const c = src[i];
    if (quoted) {
      if (c === '"' && src[i + 1] === '"') { cell += '"'; i++; }
      else if (c === '"') quoted = false;
      else cell += c;
    } else if (c === '"') quoted = true;
    else if (c === delim) { row.push(cell); cell = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && src[i + 1] === '\n') i++;
      row.push(cell); cell = '';
      rows.push(row); row = [];
    } else cell += c;
  }
  if (cell !== '' || row.length) { row.push(cell); rows.push(row); }
  return rows.filter((r) => r.some((x) => String(x).trim() !== ''));
}

const toBool = (v, fallback) => {
  const s = normalize(v);
  if (!s) return fallback;
  if (['si', 's', 'yes', 'y', 'true', '1', 'x'].includes(s)) return true;
  if (['no', 'n', 'false', '0'].includes(s)) return false;
  return null;
};

const toCount = (v) => {
  const s = String(v ?? '').trim();
  if (!s) return { value: null };
  const n = Number(s);
  return Number.isInteger(n) && n >= 0 ? { value: n } : { error: true };
};

/**
 * Parses questions from CSV text. Returns { questions, errors } where each error is
 * { row, message } (row is the line number in the file, the header being row 1) and `questions`
 * holds only the valid rows, in editor shape (options as `optionsText`).
 * `tr` translates the messages; the default returns the Spanish text.
 */
export function parseQuestionsCsv(text, tr = (s, vars) => (vars ? s.replace(/\{(\w+)\}/g, (m, k) => (k in vars ? String(vars[k]) : m)) : s)) {
  const rows = parseCsvRows(text);
  const errors = [];
  const questions = [];
  if (rows.length === 0) return { questions, errors: [{ row: 1, message: tr('El archivo está vacío.') }] };

  const header = rows[0].map(normalize);
  const col = (name) => header.indexOf(name);
  if (col('pregunta') === -1 || col('tipo') === -1) {
    return { questions, errors: [{ row: 1, message: tr('Faltan las columnas “tipo” y “pregunta” en la primera fila.') }] };
  }
  const get = (cells, name) => (col(name) === -1 ? '' : String(cells[col(name)] ?? '').trim());

  rows.slice(1).forEach((cells, i) => {
    const row = i + 2;
    const fail = (message) => errors.push({ row, message });
    const type = TYPE_NAMES[normalize(get(cells, 'tipo'))];
    const questionText = get(cells, 'pregunta');
    if (!type) return fail(tr('Tipo no reconocido: “{tipo}”.', { tipo: get(cells, 'tipo') }));
    if (!questionText) return fail(tr('Falta el texto de la pregunta.'));

    const required = toBool(get(cells, 'obligatoria'), true);
    const allowOther = toBool(get(cells, 'otro'), false);
    if (required === null || allowOther === null) return fail(tr('“obligatoria” y “otro” deben ser sí o no.'));

    const q = { type, text: questionText, required };
    if (CHOICE_TYPES.includes(type)) {
      const options = get(cells, 'opciones').split('|').map((o) => o.trim()).filter(Boolean);
      if (options.length < 2) return fail(tr('Escribe al menos 2 opciones separadas por |.'));
      q.optionsText = options.join('\n');
      q.allowOther = allowOther;
    }

    const min = toCount(get(cells, 'min'));
    const max = toCount(get(cells, 'max'));
    if (min.error || max.error) return fail(tr('“min” y “max” deben ser números enteros.'));
    if (min.value !== null && max.value !== null && min.value > max.value) return fail(tr('“min” no puede ser mayor que “max”.'));
    if (type === 'checklist') {
      if (min.value !== null) q.minSelections = min.value;
      if (max.value !== null) q.maxSelections = max.value;
    }
    if (type === 'text') {
      if (min.value !== null) q.minChars = min.value;
      if (max.value !== null) q.maxChars = max.value;
    }
    if (type === 'likert' || type === 'multiple' || type === 'checklist') {
      if (get(cells, 'etiqueta_min')) q.minLabel = get(cells, 'etiqueta_min');
      if (get(cells, 'etiqueta_max')) q.maxLabel = get(cells, 'etiqueta_max');
    }
    questions.push(q);
  });

  if (questions.length === 0 && errors.length === 0) errors.push({ row: 1, message: tr('No hay preguntas en el archivo.') });
  return { questions, errors };
}
